-- รวม 10 คำสั่งคอมไพล์ (SELECT ... WHERE 1=0 อ่านอย่างเดียว ไม่ดึงข้อมูล) -- DBeaver: Execute Script (Alt+X) ครั้งเดียว
-- ผลที่ต้องส่งกลับ: คำสั่งข้อไหน error + ข้อความ ORA-xxxxx (ดูแท็บ Execution Log / Output) -- ไม่มี error = ผ่าน

-- [1] 050200
SELECT * FROM (
SELECT CAST(TO_CHAR(process_date, 'YYYYMMDD') AS NUMBER) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,cdr_source_path ,filter_dtm ,create_by ,process_date ,status ,filter_error ,err_msg ,workflow_process_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,source_path AS cdr_source_path ,filter_dtm ,create_by ,SYSDATE as process_date ,status ,case when status='MAN' then filter_error when status='TYP' then type_error else filter_error end as filter_error ,case when status='MAN' then filter_error_msg when status='TYP' then type_error_msg else filter_error_msg end AS err_msg ,workflow_process_date FROM DSSDEV.tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM DSSDEV.tb_transaction_ss_esim_reject WHERE workflow_process_date = (SELECT workflow_process_date FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status NOT IN ('MAP', 'UNMAP') AND chk_dup_append = 0 )
) WHERE 1=0;

-- [2] 050300
SELECT * FROM (
SELECT CAST(TO_CHAR(first_installed, 'YYYYMMDD') AS NUMBER) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,cdr_source_path ,filter_dtm ,create_by ,process_date ,status, b_no ,mapping_error ,err_msg ,workflow_process_date,file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,source_path AS cdr_source_path ,filter_dtm ,create_by ,SYSDATE as process_date ,status, b_no ,mapping_error ,mapping_error_msg AS err_msg ,workflow_process_date,file_date FROM DSSDEV.tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM DSSDEV.tb_transaction_ss_esim_temp WHERE workflow_process_date = (SELECT  workflow_process_date FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status = 'UNMAP' AND chk_dup_append = 0 )
) WHERE 1=0;

-- [3] 030000
SELECT * FROM (
select 'TRUE' as running,TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') workflow_process_date FROM DUAL
) WHERE 1=0;

-- [4] 999999
SELECT * FROM (
select cdr_id,cdr_type,partner,owner,iccid,first_installed,profile_type,eid,sim_type,cp_id,service_id,before_sharing,price_rate_type,network_type,invoicing_co_id,share_basis,cdr_filename,chk_duplicate,filter_dtm,create_by,remap_dtm,remap_by,process_date,transaction_units,status,workflow_process_date,SYSDATE as bld_export_date,file_date from DSSDEV.tb_transaction_ss_esim_valid where workflow_process_date > TO_CHAR(SYSDATE-INTERVAL '7' DAY, 'YYYYMMDDHH24MISS') and workflow_process_date > (select coalesce(max_workflow_process_date_mssql,'00000000000000') as max_workflow_process_date_mssql from DSSDEV.ext_dss_checkpoint_tb_transaction_ss_esim_valid)
) WHERE 1=0;

-- [5] 020000
SELECT * FROM (
select partition_date, case when rnk in(1, 2) or checkpoint_partition <=(nth_value(checkpoint_partition, 2) over( order by checkpoint_partition)) + 300 then checkpoint_partition else min(checkpoint_partition) over (partition by partition_date) end as checkpoint_partition , process_date FROM ( SELECT CAST(TO_CHAR(process_date, 'YYYYMMDD') AS NUMBER) AS partition_date, checkpoint_partition, DENSE_RANK() OVER ( ORDER BY checkpoint_partition ASC) as rnk, process_date FROM ( SELECT DISTINCT partition_minute AS checkpoint_partition , SYSDATE AS process_date FROM DSSDEV.tb_landing_ss_esim WHERE partition_minute < TO_NUMBER(TO_CHAR(SYSDATE-INTERVAL '5' MINUTE, 'YYYYMMDDHH24MI')) AND partition_minute >= ( SELECT COALESCE(MAX(checkpoint_partition), 0) AS checkpoint_partition FROM DSSDEV.tb_staging_ss_esim_checkpoint) AND 'TRUE' = UPPER(COALESCE(( SELECT success FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status), 'TRUE'))))
) WHERE 1=0;

-- [6] 090000
SELECT * FROM (
select 'TRUE' as success FROM DUAL
) WHERE 1=0;

-- [7] 070000
SELECT * FROM (
select CAST(TO_CHAR(process_date, 'YYYYMMDD') AS NUMBER) AS partition_date,checkpoint_partition,process_date from (select checkpoint_partition,process_date from DSSDEV.tb_staging_ss_esim_checkpoint_temp)
) WHERE 1=0;

-- [8] 040000
SELECT * FROM (
SELECT CAST(TO_CHAR(process_date, 'YYYYMMDD') AS NUMBER) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,source_path ,filter_error ,filter_error_msg ,type_error ,type_error_msg ,mapping_error ,mapping_error_msg ,CASE WHEN status IS NULL AND rn = 1 AND mapping_error IS NULL THEN 'MAP' WHEN status IS NULL AND rn = 1 AND mapping_error IS NOT NULL THEN 'UNMAP' WHEN status IS NULL AND rn <> 1 THEN 'DUP' ELSE status END AS status ,filter_dtm , b_no,create_by ,process_date,workflow_process_date,CASE WHEN REGEXP_LIKE(file_date, '^[0-9]{14}$') THEN TO_TIMESTAMP(file_date DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDDHH24MISS') END as file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,source_path ,replace(filter_error,' is NULL','') filter_error ,filter_error filter_error_msg ,regexp_replace(type_error,': Invalid [A-Z]+ type \(Raw=\S*\)','') type_error ,type_error type_error_msg ,replace(mapping_error,' is NULL','') mapping_error ,mapping_error mapping_error_msg ,status ,filter_dtm , b_no,USER AS create_by ,SYSDATE AS process_date ,CASE WHEN status IS NOT NULL THEN -99 ELSE ROW_NUMBER() over(PARTITION BY chk_duplicate,status ORDER BY file_date NULLS FIRST) END AS rn , workflow_process_date,file_date FROM ( SELECT raw_.cdr_id ,raw_.cdr_type ,raw_.partner ,raw_.owner ,raw_.iccid ,raw_.first_installed ,raw_.profile_type ,raw_.eid ,raw_.sim_type ,mapping.cp_id ,mapping.service_id ,mapping.price_rate_type ,mapping.network_type ,mapping.invoicing_company_id AS invoicing_co_id ,mapping.share_basis ,raw_.cdr_filename ,raw_.chk_duplicate ,raw_.filter_dtm, raw_.b_no ,cdr_mas.source_path ,( CASE WHEN mapping.cp_id is null THEN 'cp_id is NULL|' else '' end || CASE WHEN mapping.service_id is null THEN 'service_id is NULL|' else '' end || CASE WHEN mapping.network_type is null THEN 'network_type is NULL|' else '' end || CASE WHEN mapping.invoicing_company_id is null THEN 'invoicing_company_id is NULL|' else '' end || CASE WHEN mapping.share_basis is null THEN 'share_basis is NULL|' else '' end ) AS mapping_error ,filter_error ,type_error ,CASE WHEN filter_error IS NOT NULL THEN 'MAN' WHEN type_error IS NOT NULL THEN 'TYP' WHEN dup.chk_duplicate is not null THEN 'DUP' ELSE NULL END AS status ,file_date,workflow_process_date  FROM ( SELECT (TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') || LPAD(TO_CHAR(1), 3, '0') || LPAD(TO_CHAR(ROW_NUMBER() over(ORDER BY NULL)), 9, '0')) AS cdr_id ,partner ,owner ,iccid ,CASE WHEN REGEXP_LIKE(SUBSTR(first_installed, 1, 14), '^[0-9]{14}$') THEN TO_TIMESTAMP(SUBSTR(first_installed, 1, 14) DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDDHH24MISS') END first_installed ,profile_type ,eid ,sim_type ,'1' cdr_type ,input_source_name AS cdr_filename ,chk_duplicate ,filter_dtm ,b_no ,( CASE WHEN partner is null THEN 'partner is NULL|' else '' end || CASE WHEN owner is null THEN 'owner is NULL|' else '' end || CASE WHEN iccid is null THEN 'iccid is NULL|' else '' end || CASE WHEN first_installed is null THEN 'first_installed is NULL|' else '' end || CASE WHEN profile_type is null THEN 'profile_type is NULL|' else '' end || CASE WHEN sim_type is null THEN 'sim_type is NULL|' else '' end ) AS filter_error ,( CASE WHEN CASE WHEN REGEXP_LIKE(SUBSTR(first_installed, 1, 14), '^[0-9]{14}$') THEN TO_TIMESTAMP(SUBSTR(first_installed, 1, 14) DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDDHH24MISS') END is null THEN ('first_installed: Invalid TIMESTAMP type (Raw=' || first_installed || ')|') else '' end ) AS type_error ,file_date FROM ( SELECT partner partner ,owner owner ,iccid iccid ,first_installed first_installed ,profile_type profile_type ,eid eid ,sim_type sim_type ,process_date AS filter_dtm ,partner || '_ESIM_' || sim_type AS b_no ,replace(REGEXP_SUBSTR(REGEXP_SUBSTR(input_source_name,'[^/]*$'),'(.+)(_)([0-9]{8}_[0-9]{6})(_)(.+[.].+)',1,1,NULL,3),'_','') AS file_date ,input_source_name ,coalesce(iccid,'') AS chk_duplicate FROM DSSDEV.tb_landing_ss_esim WHERE  body_tag='02' and partition_minute BETWEEN ( SELECT MIN(checkpoint_partition) FROM DSSDEV.tb_staging_ss_esim_checkpoint_temp) AND ( SELECT MAX(checkpoint_partition) FROM DSSDEV.tb_staging_ss_esim_checkpoint_temp) AND partition_minute > ( SELECT coalesce(MAX(checkpoint_partition),0) FROM DSSDEV.tb_staging_ss_esim_checkpoint) ) ) raw_ CROSS JOIN ( SELECT workflow_process_date FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status ) JOIN ( SELECT cdr_type ,source_path FROM DSSDEV.ext_dss_tb_master_cdr_type WHERE record_status = 'A' ) cdr_mas ON raw_.cdr_type = cdr_mas.cdr_type LEFT JOIN ( SELECT chk_duplicate FROM DSSDEV.tb_transaction_ss_esim_valid UNION SELECT chk_duplicate FROM DSSDEV.tb_transaction_ss_esim_temp ) dup ON raw_.chk_duplicate = dup.chk_duplicate LEFT JOIN ( SELECT distinct b_no AS b_no ,content_partner_id AS cp_id ,service_id AS service_id ,network_type AS network_type ,share_basis AS share_basis ,invoicing_company_id AS invoicing_company_id ,TRUNC(effective_date) AS effective_date ,TRUNC(expired_date) AS expired_date ,price_rate_type AS price_rate_type FROM DSSDEV.ext_dss_vw_service_mapping_bno_key WHERE record_status = 'A' AND b_no like '%\_ESIM\_%' ESCAPE '\' ) mapping ON raw_.b_no = mapping.b_no AND raw_.owner = mapping.invoicing_company_id AND mapping.effective_date <= TRUNC(raw_.first_installed) AND (mapping.expired_date is null or mapping.expired_date >= TRUNC(raw_.first_installed)) ) )
) WHERE 1=0;

-- [9] 010000
SELECT * FROM (
select success from DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status
) WHERE 1=0;

-- [10] 050100
SELECT * FROM (
SELECT CAST(TO_CHAR(first_installed, 'YYYYMMDD') AS NUMBER) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,before_sharing ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,filter_dtm ,create_by ,remap_dtm ,remap_by ,process_date ,transaction_units ,status ,workflow_process_date,file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,null as before_sharing ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,filter_dtm ,create_by ,null as remap_dtm ,null as remap_by ,SYSDATE as process_date ,'1' as transaction_units ,status ,workflow_process_date, file_date FROM DSSDEV.tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM DSSDEV.tb_transaction_ss_esim_valid WHERE status = 'MAP' AND workflow_process_date = (SELECT workflow_process_date FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status = 'MAP' AND chk_dup_append = 0 )
) WHERE 1=0;
